import{at as e,it as t,n,vt as r}from"./chunks/framework.UwwvkjGo.js";var i=JSON.parse(`{"title":"Class: Block","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/prismarine/classes/Block.md","filePath":"api/@jsprismarine/prismarine/classes/Block.md"}`),a={name:`api/@jsprismarine/prismarine/classes/Block.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/prismarine</a> / Block</p><h1 id="class-block" tabindex="-1">Class: Block <a class="header-anchor" href="#class-block" aria-label="Permalink to “Class: Block”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L112" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:112</a></p><p>One block state, as the rest of the server holds one.</p><p>A data record rather than a base class: there are no subclasses any more, because the 1477 blocks and their 22079 states come out of the pack stack and their behavior out of <code>@jsprismarine/block-behaviors</code>&#39;s 49 families. What a block yields comes from its active <code>minecraft:loot</code> component, or from the mapped Java loot table when it has no component, rather than from a method an author overrode. That is why the 260 classes this replaced were able to go.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new Block</strong>(<code>__namedParameters</code>): <code>Block</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L122" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:122</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="namedparameters" tabindex="-1">__namedParameters <a class="header-anchor" href="#namedparameters" aria-label="Permalink to “__namedParameters”">​</a></h5><p><a href="./../#blockprops"><code>BlockProps</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Block</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h3><blockquote><p><code>readonly</code> <strong>name</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L114" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:114</a></p><p>The namespaced Bedrock block identifier.</p><hr><h3 id="states" tabindex="-1">states <a class="header-anchor" href="#states" aria-label="Permalink to “states”">​</a></h3><blockquote><p><code>readonly</code> <strong>states</strong>: <code>Readonly</code>&lt;<code>Record</code>&lt;<code>string</code>, <a href="./../../blocks/#blockstatevalue"><code>BlockStateValue</code></a>&gt;&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L116" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:116</a></p><p>The state values the block carries.</p><h2 id="accessors" tabindex="-1">Accessors <a class="header-anchor" href="#accessors" aria-label="Permalink to “Accessors”">​</a></h2><h3 id="tostringtag" tabindex="-1">[toStringTag] <a class="header-anchor" href="#tostringtag" aria-label="Permalink to “[toStringTag]”">​</a></h3><h4 id="get-signature" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>[toStringTag]</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L130" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:130</a></p><h5 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h5><p><code>string</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="canbeplaced" tabindex="-1">canBePlaced() <a class="header-anchor" href="#canbeplaced" aria-label="Permalink to “canBePlaced()”">​</a></h3><blockquote><p><strong>canBePlaced</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L271" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:271</a></p><p>Whether the block can be placed at all.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="canbereplaced" tabindex="-1">canBeReplaced() <a class="header-anchor" href="#canbereplaced" aria-label="Permalink to “canBeReplaced()”">​</a></h3><blockquote><p><strong>canBeReplaced</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L251" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:251</a></p><p>Whether the block gives way to a placement rather than blocking it.</p><p>The resolved state&#39;s <code>minecraft:replaceable</code> component or tag answers for short grass, leaf litter, water, and other blocks a placement goes into instead of on top of. The client makes the same call when it predicts a placement, so a server that answered no for leaf litter put the block above it while the client showed it in the litter&#39;s place.</p><p>The tag names Java blocks, so the state goes through <code>@jsprismarine/mapping</code> first: Bedrock&#39;s <code>snow_layer</code> is Java&#39;s <code>snow</code> and its <code>deadbush</code> is Java&#39;s <code>dead_bush</code>. A block built without content has no tags to read, and only air gives way.</p><p>Snow is in the tag at every depth, but Java&#39;s snow layer block overrides it: only a single layer gives way to a placed block. Not yet measured against BDS.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="getblastresistance" tabindex="-1">getBlastResistance() <a class="header-anchor" href="#getblastresistance" aria-label="Permalink to “getBlastResistance()”">​</a></h3><blockquote><p><strong>getBlastResistance</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L207" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:207</a></p><p>Java&#39;s explosion resistance.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getbreaktime" tabindex="-1">getBreakTime() <a class="header-anchor" href="#getbreaktime" aria-label="Permalink to “getBreakTime()”">​</a></h3><blockquote><p><strong>getBreakTime</strong>(<code>item</code>, <code>_server?</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L194" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:194</a></p><p>How long, in seconds, the block takes to break.</p><p>Hardness on its own is not that time. Vanilla scales it by whether the tool in hand can actually harvest the block - 1.5x when it can, 5x when it cannot, which is why dirt takes 0.75s by hand and stone 7.5s - and then divides by how fast the tool mines. Those two factors are Java&#39;s <code>destroyProgress</code> written the other way up: <code>speed / hardness / 30</code> for a correct tool and <code>/ 100</code> for anything else, in progress per tick.</p><p>The divisor is what Efficiency moves: the enchantment is an <code>add_value</code> on <code>minecraft:mining_efficiency</code>, which Java adds to the tool&#39;s speed.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="item" tabindex="-1">item <a class="header-anchor" href="#item" aria-label="Permalink to “item”">​</a></h5><p><a href="./Item.html"><code>Item</code></a> | <code>null</code></p><p>What is in hand, or null for a bare fist.</p><h5 id="server" tabindex="-1">_server? <a class="header-anchor" href="#server" aria-label="Permalink to “_server?”">​</a></h5><p><code>unknown</code></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getdrops" tabindex="-1">getDrops() <a class="header-anchor" href="#getdrops" aria-label="Permalink to “getDrops()”">​</a></h3><blockquote><p><strong>getDrops</strong>(<code>item</code>, <code>server?</code>): (<a href="./Item.html"><code>Item</code></a> | <code>Block</code> | <code>null</code>)[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L314" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:314</a></p><p>What the block yields when it breaks, from its active loot component or its mapped Java loot table.</p><p>Silk touch, fortune, the shears branches and gravel&#39;s one-in-ten flint are in the table rather than here, so this is a roll rather than a decision tree. A server with no content build has no tables to roll and yields the block itself.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="item-1" tabindex="-1">item <a class="header-anchor" href="#item-1" aria-label="Permalink to “item”">​</a></h5><p><a href="./Item.html"><code>Item</code></a> | <code>null</code></p><p>What broke it, which the table&#39;s predicates read.</p><h5 id="server-1" tabindex="-1">server? <a class="header-anchor" href="#server-1" aria-label="Permalink to “server?”">​</a></h5><p><a href="./../#blockdropserver"><code>BlockDropServer</code></a></p><p>The server, for its content and its source of chance.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p>(<a href="./Item.html"><code>Item</code></a> | <code>Block</code> | <code>null</code>)[]</p><hr><h3 id="getflammability" tabindex="-1">getFlammability() <a class="header-anchor" href="#getflammability" aria-label="Permalink to “getFlammability()”">​</a></h3><blockquote><p><strong>getFlammability</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L222" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:222</a></p><p>Fire&#39;s odds of consuming the block once lit.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getfriction" tabindex="-1">getFriction() <a class="header-anchor" href="#getfriction" aria-label="Permalink to “getFriction()”">​</a></h3><blockquote><p><strong>getFriction</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L227" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:227</a></p><p>Ground friction, which decides how far a player slides across the block.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="gethardness" tabindex="-1">getHardness() <a class="header-anchor" href="#gethardness" aria-label="Permalink to “getHardness()”">​</a></h3><blockquote><p><strong>getHardness</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L175" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:175</a></p><p>Java&#39;s destroy time in seconds; <code>-1</code> marks the unbreakable blocks.</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getjavatags" tabindex="-1">getJavaTags() <a class="header-anchor" href="#getjavatags" aria-label="Permalink to “getJavaTags()”">​</a></h3><blockquote><p><strong>getJavaTags</strong>(): readonly <code>string</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L158" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:158</a></p><p>The Java datapack tags attached to this Bedrock block type.</p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <code>string</code>[]</p><hr><h3 id="getlightfilter" tabindex="-1">getLightFilter() <a class="header-anchor" href="#getlightfilter" aria-label="Permalink to “getLightFilter()”">​</a></h3><blockquote><p><strong>getLightFilter</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L217" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:217</a></p><p>How much light the block swallows, 0 to 15.</p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getlightlevel" tabindex="-1">getLightLevel() <a class="header-anchor" href="#getlightlevel" aria-label="Permalink to “getLightLevel()”">​</a></h3><blockquote><p><strong>getLightLevel</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L212" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:212</a></p><p>The light the block emits, 0 to 15.</p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getname" tabindex="-1">getName() <a class="header-anchor" href="#getname" aria-label="Permalink to “getName()”">​</a></h3><blockquote><p><strong>getName</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L138" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:138</a></p><p>The block&#39;s namespaced identifier.</p><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="getstatename" tabindex="-1">getStateName() <a class="header-anchor" href="#getstatename" aria-label="Permalink to “getStateName()”">​</a></h3><blockquote><p><strong>getStateName</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L143" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:143</a></p><p>The vanilla block state to place, which is <a href="#name">name</a> unless overridden.</p><h4 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="gettags" tabindex="-1">getTags() <a class="header-anchor" href="#gettags" aria-label="Permalink to “getTags()”">​</a></h3><blockquote><p><strong>getTags</strong>(): readonly <code>string</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L148" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:148</a></p><p>The Bedrock tags attached to this block state, or an empty list when it has no type.</p><h4 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <code>string</code>[]</p><hr><h3 id="hasjavatag" tabindex="-1">hasJavaTag() <a class="header-anchor" href="#hasjavatag" aria-label="Permalink to “hasJavaTag()”">​</a></h3><blockquote><p><strong>hasJavaTag</strong>(<code>tag</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L168" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:168</a></p><p>Whether a Java datapack tag includes this block type.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tag" tabindex="-1">tag <a class="header-anchor" href="#tag" aria-label="Permalink to “tag”">​</a></h5><p><code>string</code></p><h4 id="returns-16" tabindex="-1">Returns <a class="header-anchor" href="#returns-16" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="hastag" tabindex="-1">hasTag() <a class="header-anchor" href="#hastag" aria-label="Permalink to “hasTag()”">​</a></h3><blockquote><p><strong>hasTag</strong>(<code>tag</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L153" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:153</a></p><p>Whether this block state carries one of its Bedrock tags.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tag-1" tabindex="-1">tag <a class="header-anchor" href="#tag-1" aria-label="Permalink to “tag”">​</a></h5><p><code>string</code></p><h4 id="returns-17" tabindex="-1">Returns <a class="header-anchor" href="#returns-17" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="isbreakable" tabindex="-1">isBreakable() <a class="header-anchor" href="#isbreakable" aria-label="Permalink to “isBreakable()”">​</a></h3><blockquote><p><strong>isBreakable</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L276" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:276</a></p><p>Whether mining ever removes the block.</p><h4 id="returns-18" tabindex="-1">Returns <a class="header-anchor" href="#returns-18" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="iscompatiblewithtool" tabindex="-1">isCompatibleWithTool() <a class="header-anchor" href="#iscompatiblewithtool" aria-label="Permalink to “isCompatibleWithTool()”">​</a></h3><blockquote><p><strong>isCompatibleWithTool</strong>(<code>item</code>, <code>content?</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L296" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:296</a></p><p>Whether what is in hand harvests the block rather than destroying it for nothing.</p><p>Java&#39;s rule in one line: a block without <code>requires_correct_tool</code> yields to anything, including a bare fist, and one with it yields only to a tool whose <code>minecraft:tool</code> rules say the block is correct for drops.</p><p>A server with no content build answers yes either way. Those rules name their blocks by tag - <code>#minecraft:mineable/pickaxe</code>, <code>#minecraft:incorrect_for_stone_tool</code> - and the merged tag set only exists once a pack stack is loaded, so without one no tool could ever read as the right one and nothing needing a tool would drop at all.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="item-2" tabindex="-1">item <a class="header-anchor" href="#item-2" aria-label="Permalink to “item”">​</a></h5><p><a href="./Item.html"><code>Item</code></a> | <code>null</code></p><p>What is in hand, or null for a bare fist.</p><h5 id="content" tabindex="-1">content? <a class="header-anchor" href="#content" aria-label="Permalink to “content?”">​</a></h5><p><a href="./../#servercontent"><code>ServerContent</code></a> | <code>undefined</code> = <code>...</code></p><h4 id="returns-19" tabindex="-1">Returns <a class="header-anchor" href="#returns-19" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="ispartofcreativeinventory" tabindex="-1">isPartOfCreativeInventory() <a class="header-anchor" href="#ispartofcreativeinventory" aria-label="Permalink to “isPartOfCreativeInventory()”">​</a></h3><blockquote><p><strong>isPartOfCreativeInventory</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L330" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:330</a></p><p>Whether the creative menu shows the block.</p><h4 id="returns-20" tabindex="-1">Returns <a class="header-anchor" href="#returns-20" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="issolid" tabindex="-1">isSolid() <a class="header-anchor" href="#issolid" aria-label="Permalink to “isSolid()”">​</a></h3><blockquote><p><strong>isSolid</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L232" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:232</a></p><p>Whether anything can stand on the block.</p><h4 id="returns-21" tabindex="-1">Returns <a class="header-anchor" href="#returns-21" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="tostring" tabindex="-1">toString() <a class="header-anchor" href="#tostring" aria-label="Permalink to “toString()”">​</a></h3><blockquote><p><strong>toString</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3a31aca0639d5d390ee54fea52c63a116701f9c3/packages/prismarine/src/block/Block.ts#L133" target="_blank" rel="noreferrer">prismarine/src/block/Block.ts:133</a></p><h4 id="returns-22" tabindex="-1">Returns <a class="header-anchor" href="#returns-22" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p>`,210)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};